import { useEffect, useState } from 'react';
import { supabaseClient } from '../lib/supabase';

const App = () => {
  const [data, setData] = useState([]);
  useEffect(() => {
    async function fetchData() {
      const { data: users, error } = await supabaseClient
        .from('users')
        .select('*');
      if (error) {
        console.error(error);
      } else {
        setData(users);
      }
    }
    fetchData();
  }, []);
  return (
    <div>
      {data.map((user) => (
        <div key={user.id}>{user.name}</div>
      ))}
    </div>
  );
};
export default App;

